    bg = max(counts, key=counts.get)

    # Find repeated-color bars on opposite edges.
    pairs = []
    # Each bar: orientation, edge, start, end, color.
    for side in ("top", "bottom"):
        r = 0 if side == "top" else h - 1
        c = 0
        while c < w:
            color = grid[r][c]
            end = c
            while end + 1 < w and grid[r][end + 1] == color:
                end += 1
            if color != bg and end > c:
                pairs.append(("horizontal", side, c, end, color))
            c = end + 1
    for side in ("left", "right"):
        c = 0 if side == "left" else w - 1
        r = 0
        while r < h:
            color = grid[r][c]
            end = r
            while end + 1 < h and grid[end + 1][c] == color:
                end += 1
            if color != bg and end > r:
                pairs.append(("vertical", side, r, end, color))
            r = end + 1

    chosen = None
    for a in pairs:
        for b in pairs:
            if a[0] != b[0] or a[1] == b[1] or a[4] != b[4]:
                continue
            if a[3] - a[2] != b[3] - b[2]:
                continue
            chosen = (a, b)
            break
        if chosen:
            break
    if not chosen:
        return out

    a, b = chosen
    emitter = a[4]
    targets = [v for v in counts if v != bg and v != emitter]
    if not targets:
        return out
    target = min(targets, key=lambda v: counts[v])

    # The target markers determine active offsets along the paired bars.
    offsets = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == target:
                pos = c if a[0] == "horizontal" else r
                for bar in (a, b):
                    if bar[2] <= pos <= bar[3]:
                        offsets.add(pos - bar[2])
    if not offsets:
        return out

    for bar in (a, b):
        orient, side, start, end, _ = bar
        for off in offsets:
            if start + off > end:
                continue
            if orient == "horizontal":
                r = 0 if side == "top" else h - 1
                c = start + off
                dr = 1 if side == "top" else -1
                dc = 0
            else:
                r = start + off
                c = 0 if side == "left" else w - 1
                dr = 0
                dc = 1 if side == "left" else -1

